import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as n,c as e,f as l,q as a,D as r,P as p,g as h}from"./chunks/runtime-core.esm-bundler.BfuZi_fv.js";const y=JSON.parse('{"title":"容器存储","description":"","frontmatter":{},"headers":[],"relativePath":"column/Docker/基础/容器存储.md","filePath":"column/Docker/基础/容器存储.md","lastUpdated":1785548202000}'),o={name:"column/Docker/基础/容器存储.md"};function d(k,s,c,u,g,m){const i=n("ArticleMetadata");return l(),e("div",null,[s[0]||(s[0]=a("h1",{id:"容器存储",tabindex:"-1"},[h("容器存储 "),a("a",{class:"header-anchor",href:"#容器存储","aria-label":'Permalink to "容器存储"'},"​")],-1)),r(i),s[1]||(s[1]=p(`<nav class="table-of-contents"><ul><li><a href="#核心持久化方式对比">核心持久化方式对比</a></li><li><a href="#三种挂载方式详解">三种挂载方式详解</a><ul><li><a href="#_1-volumes-数据卷-——-生产环境的首选">1. Volumes（数据卷）—— 生产环境的首选</a></li><li><a href="#_2-bind-mounts-绑定挂载-——-开发调试的最佳助手">2. Bind Mounts（绑定挂载）—— 开发调试的最佳助手</a></li><li><a href="#_3-tmpfs-mounts-内存挂载-——-临时敏感数据">3. tmpfs Mounts（内存挂载）—— 临时敏感数据</a></li></ul></li><li><a href="#底层原理-联合文件系统-overlayfs">底层原理：联合文件系统（OverlayFS）</a></li></ul></nav><p>Docker 的存储机制是理解容器特性的关键。默认情况下，在容器内部创建的所有文件都存储在一个可写容器层（Container Layer）中。这种默认机制带来两个核心问题：</p><ol><li><strong>生命周期绑定</strong>：容器销毁时，其内部产生的数据也会随之丢失。</li><li><strong>性能与移植性较差</strong>：写时复制（CoW）机制会导致写入性能低于普通文件系统，且数据难以在宿主机与其他容器间共享。</li></ol><p>为了解决数据持久化和共享问题，Docker 提供了三种主要的挂载存储方式：</p><h2 id="核心持久化方式对比" tabindex="-1">核心持久化方式对比 <a class="header-anchor" href="#核心持久化方式对比" aria-label="Permalink to &quot;核心持久化方式对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>存储类型</th><th>宿主机存储位置</th><th>管理方式</th><th>最佳适用场景</th></tr></thead><tbody><tr><td><strong>Volume（数据卷）</strong></td><td><code>/var/lib/docker/volumes/</code></td><td>Docker 完全托管</td><td>数据库数据、生产环境持久化、容器间共享数据</td></tr><tr><td><strong>Bind Mount（绑定挂载）</strong></td><td>宿主机任意绝对路径</td><td>用户直接管理</td><td>本地代码开发调试、共享宿主机的配置文件</td></tr><tr><td><strong>tmpfs Mount（内存挂载）</strong></td><td>仅存储在宿主机内存（RAM）中</td><td>系统内存隔离</td><td>敏感信息（密钥/密码）、高频读写的临时高速缓存</td></tr></tbody></table><h2 id="三种挂载方式详解" tabindex="-1">三种挂载方式详解 <a class="header-anchor" href="#三种挂载方式详解" aria-label="Permalink to &quot;三种挂载方式详解&quot;">​</a></h2><h3 id="_1-volumes-数据卷-——-生产环境的首选" tabindex="-1">1. Volumes（数据卷）—— 生产环境的首选 <a class="header-anchor" href="#_1-volumes-数据卷-——-生产环境的首选" aria-label="Permalink to &quot;1. Volumes（数据卷）—— 生产环境的首选&quot;">​</a></h3><p>数据卷是由 Docker 维护的独立存储空间，独立于容器的生命周期。</p><ul><li><strong>优点</strong>：由 Docker 统一管理，迁移和备份方便；性能高于可写容器层；支持第三方卷驱动（如 NFS、云存储）。</li><li><strong>常用命令</strong>：</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建数据卷</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_data</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用 -v 挂载数据卷到容器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_data:/app/data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_2-bind-mounts-绑定挂载-——-开发调试的最佳助手" tabindex="-1">2. Bind Mounts（绑定挂载）—— 开发调试的最佳助手 <a class="header-anchor" href="#_2-bind-mounts-绑定挂载-——-开发调试的最佳助手" aria-label="Permalink to &quot;2. Bind Mounts（绑定挂载）—— 开发调试的最佳助手&quot;">​</a></h3><p>将宿主机上的某个具体文件或目录直接挂载到容器内部。</p><ul><li><strong>优点</strong>：实时同步！在宿主机修改代码或配置，容器内立刻生效。</li><li><strong>注意</strong>：强依赖宿主机的目录结构；如果挂载到的容器目录非空，宿主机目录会直接覆盖容器内的原始文件。</li><li><strong>示例</strong>：</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将宿主机的 /home/user/app 目录挂载到容器的 /app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/user/app:/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-tmpfs-mounts-内存挂载-——-临时敏感数据" tabindex="-1">3. tmpfs Mounts（内存挂载）—— 临时敏感数据 <a class="header-anchor" href="#_3-tmpfs-mounts-内存挂载-——-临时敏感数据" aria-label="Permalink to &quot;3. tmpfs Mounts（内存挂载）—— 临时敏感数据&quot;">​</a></h3><p>数据不会写入磁盘，而是直接保存在宿主机内存中。容器停止后，内存中的数据会自动清除。</p><ul><li><strong>优点</strong>：读写性能极高，且不会在磁盘留下敏感痕迹（如密码、Token）。</li><li><strong>示例</strong>：</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tmpfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="底层原理-联合文件系统-overlayfs" tabindex="-1">底层原理：联合文件系统（OverlayFS） <a class="header-anchor" href="#底层原理-联合文件系统-overlayfs" aria-label="Permalink to &quot;底层原理：联合文件系统（OverlayFS）&quot;">​</a></h2><p>当容器向内部写数据时，Docker 使用了 <strong>OverlayFS</strong> 联合文件系统：</p><ul><li><strong>镜像层（ReadOnly）</strong>：底层多个只读层，所有容器共享。</li><li><strong>容器层（ReadWrite）</strong>：最顶部的一个可写层。</li><li><strong>写时复制（Copy-on-Write, CoW）</strong>：当容器尝试修改镜像层中的已有文件时，Docker 会先将该文件复制一份到顶层的容器层，然后再进行修改。这种设计极大地节省了磁盘空间。</li></ul>`,22))])}const C=t(o,[["render",d]]);export{y as __pageData,C as default};
